/**
 * Localizes a crop variety string e.g. "Sugarcane (Co 86032)" or "Plot A - Sugarcane (Co 86032)"
 */
export function localizePlotOrCropName(text: string | undefined | null, lang: LanguageCode): string {
  if (!text) return '';
  if (lang === 'en') return text;

  let result = text;

  // Replace crops
  for (const [englishCrop, translations] of Object.entries(CROP_TRANSLATIONS)) {
    const localized = translations[lang];
    if (localized) {
      result = result.replace(new RegExp(englishCrop, 'g'), localized);
    }
  }

  // Replace common terms like "Plot", "Drip Lateral", "Intercrop Zone"
  for (const [englishTerm, translations] of Object.entries(COMMON_TERMS)) {
    const localized = translations[lang];
    if (localized) {
      result = result.replace(new RegExp(englishTerm, 'g'), localized);
    }
  }

  return result;
}

/**
 * Localizes freshness timestamps e.g. "Updated 29 minutes ago", "Updated just now"
 */
export function localizeDataFreshness(freshness: string | undefined, lang: LanguageCode): string {
  if (!freshness) return '';
  if (lang === 'en') return freshness;

  const match = freshness.match(/Updated\s+(\d+)\s+minutes\s+ago/i);
  if (match) {
    const mins = match[1];
    switch (lang) {
      case 'mr':
        return `${mins} मिनिटांपूर्वी अद्ययावत`;
      case 'hi':
        return `${mins} मिनट पहले अपडेट किया गया`;
      case 'ta':
        return `${mins} நிமிடங்களுக்கு முன்பு புதுப்பிக்கப்பட்டது`;
      case 'te':
        return `${mins} నిమిషాల క్రితం నవీకరించబడింది`;
      case 'kn':
        return `${mins} ನಿಮಿಷಗಳ ಹಿಂದೆ ನವೀಕರಿಸಲಾಗಿದೆ`;
      case 'gu':
        return `${mins} મિનિટ પહેલાં અપડેટ કરાયું`;
      case 'bn':
        return `${mins} মিনিট আগে আপডেট করা হয়েছে`;
      case 'pa':
        return `${mins} ਮਿੰਟ ਪਹਿਲਾਂ ਅੱਪਡੇਟ ਕੀਤਾ`;
      case 'ml':
        return `${mins} മിനിറ്റ് മുൻപ് അപ്ഡേറ്റ് ചെയ്തു`;
      default:
        return freshness;
    }
  }

  if (/just\s+now/i.test(freshness)) {
    switch (lang) {
      case 'mr':
        return 'आत्ताच अद्ययावत';
      case 'hi':
        return 'अभी अपडेट किया गया';
      case 'ta':
        return 'இப்போது புதுப்பிக்கப்பட்டது';
      case 'te':
        return 'ఇప్పుడే నవీకరించబడింది';
      case 'kn':
        return 'ಈಗಷ್ಟೇ ನವೀಕರಿಸಲಾಗಿದೆ';
      case 'gu':
        return 'હમણાં જ અપડેટ કર્યું';
      case 'bn':
        return 'এইমাত্র আপডেট হয়েছে';
      case 'pa':
        return 'ਹੁਣੇ ਅੱਪਡੇਟ ਕੀਤਾ';
      case 'ml':
        return 'ഇപ്പോൾ അപ്ഡേറ്റ് ചെയ്തു';
      default:
        return freshness;
    }
  }

  return freshness;
}

/**
 * Localizes alert reason text dynamically across languages
 */
export function localizeAlertReason(reason: string, lang: LanguageCode): string {
  if (!reason || lang === 'en') return reason;

  // Case 1: "Soil moisture at 27.4% is critically below tolerable threshold (45.0%) for Sugarcane."
  const critMatch = reason.match(/Soil moisture at ([\d.]+)% is critically below tolerable threshold \(([\d.]+)%\) for (.+)\.?/i);
  if (critMatch) {
    const val = critMatch[1];
    const thresh = critMatch[2];
    const crop = critMatch[3].trim().replace(/\.$/, '');
    const localizedCrop = CROP_TRANSLATIONS[crop]?.[lang] || crop;

    switch (lang) {
      case 'mr':
        return `${localizedCrop} पिकासाठी मातीतील ओलावा ${val}% अत्यंत गंभीर असून सहनशील मर्यादेपेक्षा (${thresh}%) खाली आहे.`;
      case 'hi':
        return `${localizedCrop} के लिए मृदा नमी ${val}% अत्यंत गंभीर रूप से सहनीय सीमा (${thresh}%) से नीचे है।`;
      case 'ta':
        return `${localizedCrop} பயிருக்கு மண் ஈரப்பதம் ${val}% ஆக மிகக் குறைவாக சகிப்புத்தன்மை வரம்புக்கு (${thresh}%) கீழே உள்ளது.`;
      case 'te':
        return `${localizedCrop} పంటకు నేల తేమ ${val}% వద్ద ప్రమాదకరంగా సహన పరిమితి (${thresh}%) కంటే తక్కువగా ఉంది.`;
      case 'kn':
        return `${localizedCrop} ಬೆಳೆಗೆ ಮಣ್ಣಿನ ತೇವಾಂಶ ${val}% ಸಹನೀಯ ಮಿತಿಗಿಂತ (${thresh}%) ತೀವ್ರವಾಗಿ ಕೆಳಗಿದೆ.`;
      case 'gu':
        return `${localizedCrop} માટે માટીનો ભેજ ${val}% ખૂબ જ ગંભીર રીતે સહનશીલ મર્યાદા (${thresh}%) કરતાં નીચે છે.`;
      case 'bn':
        return `${localizedCrop} আবাদের জন্য মাটির আর্দ্রতা ${val}% সহনীয় সীমার (${thresh}%) মারাত্মক নিচে রয়েছে।`;
      case 'pa':
        return `${localizedCrop} ਲਈ ਮਿੱਟੀ ਦੀ ਨਮੀ ${val}% ਨਾਜ਼ੁਕ ਤੌਰ 'ਤੇ ਸਹਿਣਯੋਗ ਸੀਮਾ (${thresh}%) ਤੋਂ ਘੱਟ ਹੈ।`;
      case 'ml':
        return `${localizedCrop} വിളയ്ക്ക് മണ്ണിന്റെ ഈർപ്പം ${val}% താങ്ങാവുന്ന പരിധിക്ക് (${thresh}%) വളരെ താഴെയാണ്.`;
      default:
        return reason;
    }
  }

  // Case 2: "Soil moisture at 54.2% is below optimal range [60-80%] for Sugarcane."
  const optMatch = reason.match(/Soil moisture at ([\d.]+)% is below optimal range \[([\d-]+)%\] for (.+)\.?/i);
  if (optMatch) {
    const val = optMatch[1];
    const range = optMatch[2];
    const crop = optMatch[3].trim().replace(/\.$/, '');
    const localizedCrop = CROP_TRANSLATIONS[crop]?.[lang] || crop;

    switch (lang) {
      case 'mr':
        return `${localizedCrop} पिकासाठी मातीतील ओलावा ${val}% योग्य मर्यादा [${range}%] पेक्षा कमी आहे.`;
      case 'hi':
        return `${localizedCrop} के लिए मृदा नमी ${val}% इष्टतम सीमा [${range}%] से कम है।`;
      case 'ta':
        return `${localizedCrop} பயிருக்கு மண் ஈரப்பதம் ${val}% உகந்த வரம்பிற்கு [${range}%] கீழே உள்ளது.`;
      case 'te':
        return `${localizedCrop} పంటకు నేల తేమ ${val}% సరైన పరిధి [${range}%] కంటే తక్కువగా ఉంది.`;
      case 'kn':
        return `${localizedCrop} ಬೆಳೆಗೆ ಮಣ್ಣಿನ ತೇವಾಂಶ ${val}% ಸೂಕ್ತ ಶ್ರೇಣಿಗಿಂತ [${range}%] ಕಡಿಮೆಯಾಗಿದೆ.`;
      case 'gu':
        return `${localizedCrop} માટે માટીનો ભેજ ${val}% યોગ્ય મર્યાદા [${range}%] કરતાં ઓછો છે.`;
      case 'bn':
        return `${localizedCrop} আবাদের জন্য মাটির আর্দ্রতা ${val}% আদর্শ পরিসরের [${range}%] নিচে রয়েছে।`;
      case 'pa':
        return `${localizedCrop} ਲਈ ਮਿੱਟੀ ਦੀ ਨਮੀ ${val}% ਅਨੁਕੂਲ ਸੀਮਾ [${range}%] ਤੋਂ ਹੇਠਾਂ ਹੈ।`;
      case 'ml':
        return `${localizedCrop} വിളയ്ക്ക് മണ്ണിന്റെ ഈർപ്പം ${val}% അനുയോജ്യമായ പരിധിക്ക് [${range}%] താഴെയാണ്.`;
      default:
        return reason;
    }
  }

  return reason;
}

/**
 * Localizes recommended actions for agronomic alerts
 */
export function localizeAlertAction(action: string, lang: LanguageCode): string {
  if (!action || lang === 'en') return action;

  if (/Flush and unblock drip lateral/i.test(action)) {
    switch (lang) {
      case 'mr':
        return 'ठिबक लॅटरल ४ त्वरित फ्लश करून अडथळा दूर करा; संबंधित क्षेत्रास सलग ३.५ तास पाणी द्या.';
      case 'hi':
        return 'ड्रिप लेटरल ४ को तुरंत फ्लश कर साफ़ करें; क्षेत्र को लगातार ३.५ घंटे सींचें।';
      case 'ta':
        return 'சொட்டு நீர் லேட்டரல் 4-ஐ உடனடியாக சுத்தம் செய்து அடைப்பை நீக்கவும்; பகுதிக்கு தொடர்ந்து 3.5 மணி நேரம் பாசனம் செய்யவும்.';
      case 'te':
        return 'డ్రిప్ లేటరల్ 4 ని వెంటనే ఫ్లష్ చేసి అడ్డంకిని తొలగించండి; ఆ జోన్‌కు నిరంతరం 3.5 గంటలు నీరందించండి.';
      case 'kn':
        return 'ಹನಿ ನೀರಾವರಿ ಲೇಟರಲ್ 4 ನ್ನು ತಕ್ಷಣ ಫ್ಲಶ್ ಮಾಡಿ ಅಡೆತಡೆ ತೆಗೆಯಿರಿ; ವಲಯಕ್ಕೆ ನಿರಂತರ 3.5 ಗಂಟೆಗಳ ಕಾಲ ನೀರುಣಿಸಿ.';
      case 'gu':
        return 'ડ્રિપ લેટરલ ૪ ને તાત્કાલિક ફ્લશ કરી અવરોધ દૂર કરો; વિસ્તારમાં સતત ૩.૫ કલાક પાણી આપો.';
      case 'bn':
        return 'ড্রিপ ল্যাটারাল ৪ অবিলম্বে ফ্লাশ করে বাধা দূর করুন; এলাকায় টানা ৩.৫ ঘন্টা সেচ দিন।';
      case 'pa':
        return 'ਡ੍ਰਿੱਪ ਲੈਟਰਲ 4 ਨੂੰ ਤੁਰੰਤ ਫਲੱਸ਼ ਕਰੋ ਅਤੇ ਰੁਕਾਵਟ ਦੂਰ ਕਰੋ; ਜ਼ੋਨ ਨੂੰ ਲਗਾਤਾਰ 3.5 ਘੰਟੇ ਸਿੰਜਾਈ ਕਰੋ।';
      case 'ml':
        return 'ഡ്രിപ്പ് ലാറ്ററൽ 4 ഉടൻ ഫ്ലഷ് ചെയ്ത് തടസ്സം നീക്കുക; മേഖലയിൽ തുടർച്ചയായി 3.5 മണിക്കൂർ നനയ്ക്കുക.';
      default:
        return action;
    }
  }

  if (/Increase drip cycle duration/i.test(action)) {
    switch (lang) {
      case 'mr':
        return 'पुढील २४ तासांत ठिबक सिंचनाचा कालावधी ४५ मिनिटांनी वाढवा.';
      case 'hi':
        return 'अगले २४ घंटों में ड्रिप सिंचाई चक्र की अवधि ४५ मिनट बढ़ाएँ।';
      case 'ta':
        return 'அடுத்த 24 மணி நேரத்தில் சொட்டு நீர் பாசன நேரத்தை 45 நிமிடங்கள் அதிகரிக்கவும்.';
      case 'te':
        return 'రాబోయే 24 గంటల్లో డ్రిప్ సైకిల్ వ్యవధిని 45 నిమిషాలు పెంచండి.';
      case 'kn':
        return 'ಮುಂದಿನ 24 ಗಂಟೆಗಳಲ್ಲಿ ಹನಿ ನೀರಾವರಿ ಚಕ್ರದ ಅವಧಿಯನ್ನು 45 ನಿಮಿಷಗಳಷ್ಟು ಹೆಚ್ಚಿಸಿ.';
      case 'gu':
        return 'આગામી ૨૪ કલાકમાં ડ્રિપ સાયકલનો સમયગાળો ૪૫ મિનિટ વધારો.';
      case 'bn':
        return 'পরবর্তী ২৪ ঘণ্টায় ড্রিপ চক্রের সময়কাল ৪৫ মিনিট বাড়ান।';
      case 'pa':
        return 'ਅਗਲੇ 24 ਘੰਟਿਆਂ ਵਿੱਚ ਡ੍ਰਿੱਪ ਸਿੰਚਾਈ ਦਾ ਸਮਾਂ 45 ਮਿੰਟ ਵਧਾਓ।';
      case 'ml':
        return 'അടുത്ത 24 മണിക്കൂറിനുള്ളിൽ ഡ്രിപ്പ് സൈക്കിൾ ദൈർഘ്യം 45 മിനിറ്റ് വർദ്ധിപ്പിക്കുക.';
      default:
        return action;
    }
  }

  return action;
}

/**
 * Localizes "Target:" label
 */
export function getTargetLabel(lang: LanguageCode): string {
  switch (lang) {
    case 'mr':
      return 'लक्ष्य:';
    case 'hi':
      return 'लक्ष्य:';
    case 'ta':
      return 'இலக்கு:';
    case 'te':
      return 'లక్ష్యం:';
    case 'kn':
      return 'ಗುರಿ:';
    case 'gu':
      return 'લક્ષ્ય:';
    case 'bn':
      return 'টার্গেট:';
    case 'pa':
      return 'ਨਿਸ਼ਾਨਾ:';
    case 'ml':
      return 'ലക്ഷ്യം:';
    default:
      return 'Target:';
  }
}

/**
 * Localizes "Agronomic Separation Rule:" title
 */
export function getAgronomicRuleTitle(lang: LanguageCode): string {
  switch (lang) {
    case 'mr':
      return 'कृषी पडताळणी नियम:';
    case 'hi':
      return 'कृषि पृथक्करण नियम:';
    case 'ta':
      return 'வேளாண் சரிபார்ப்பு விதி:';
    case 'te':
      return 'వ్యవసాయ వేర్పాటు నియమం:';
    case 'kn':
      return 'ಕೃಷಿ ಪ್ರತ್ಯೇಕತೆಯ ನಿಯಮ:';
    case 'gu':
      return 'કૃષિ વિભાજન નિયમ:';
    case 'bn':
      return 'কৃষি পৃথকীকরণ নিয়ম:';
    case 'pa':
      return 'ਖੇਤੀਬਾੜੀ ਵੱਖਰਾ ਨਿਯਮ:';
    case 'ml':
      return 'കാർഷിക വേർതിരിക്കൽ ചട്ടം:';
    default:
      return 'Agronomic Separation Rule:';
  }
}

