    statutoryNoticeDesc: {
      en: 'This document is a technical field verification record compiled under the AgriSurvey platform based on farmer photographic submissions and authorized drone aerial photogrammetry. This verification record does NOT constitute legal proof of title, ownership certification, or conclusive registry of property ownership.',
      mr: 'हा दस्तऐवज शेतकऱ्यांनी सादर केलेले फोटो आणि अधिकृत ड्रोन फोटोग्रामेट्रीवर आधारित अ‍ॅग्रीसर्व्हे प्रणालीद्वारे तयार केलेला तांत्रिक प्रत्यक्ष पाहणी अहवाल आहे. हा पडताळणी अहवाल मालकी हक्काचा कायदेशीर पुरावा, मालकीचे प्रमाणपत्र किंवा जमिनीच्या मालकीची अंतिम नोंद मानला जात नाही.',
      hi: 'यह दस्तावेज किसान फोटोग्राफिक प्रस्तुतियों और अधिकृत ड्रोन हवाई चित्रों के आधार पर एग्रीसर्वे प्लेटफॉर्म के तहत तैयार किया गया तकनीकी सत्यापन रिकॉर्ड है। यह सत्यापन रिकॉर्ड स्वामित्व का कानूनी प्रमाण या स्वामित्व प्रमाणन नहीं है।',
      ta: 'இந்த ஆவணம் விவசாயி புகைப்படங்கள் மற்றும் அங்கீகரிக்கப்பட்ட ட்ரோன் புகைப்படங்களின் அடிப்படையில் அக்ரிசர்வே தளத்தின் கீழ் தயாரிக்கப்பட்ட தொழில்நுட்ப ஆய்வு பதிவாகும். இது சட்டப்பூர்வ உரிமை சான்றிதழாகாது.',
      te: 'ఈ పత్రం రైతు ఫోటోలు మరియు డ్రోన్ చిత్రాల ఆధారంగా AgriSurvey ప్లాట్‌ఫామ్ కింద రూపొందించబడిన సాంకేతిక నివేదిక. ఇది యాజమాన్య చట్టపరమైన రుజువు కాదు.',
      kn: 'ಈ ದಾಖಲೆಯು ರೈತರ ಫೋಟೋಗಳು ಮತ್ತು ಡ್ರೋನ್ ಚಿತ್ರಗಳ ಆಧಾರದ ಮೇಲೆ AgriSurvey ಅಡಿಯಲ್ಲಿ ಸಿದ್ಧಪಡಿಸಲಾದ ತಾಂತ್ರಿಕ ದಾಖಲೆಯಾಗಿದೆ. ಇದು ಮಾಲೀಕತ್ವದ ಕಾನೂನು ಪುರಾವೆಯಲ್ಲ.',
      gu: 'આ દસ્તાવેજ ખેડૂતના ફોટા અને અધિકૃત ડ્રોન ફોટોગ્રામેટ્રી પર આધારિત એક તકનીકી ચકાસણી રેકોર્ડ છે. આ કાનૂની માલિકીનો પુરાવો નથી.',
      bn: 'এই নথিটি কৃষকের ছবি এবং অনুমোদিত ড্রোন ফটোগ্রাফির ভিত্তিতে প্রস্তুতকৃত একটি প্রযুক্তিগত রেকর্ড। এটি আইনি মালিকানার চূড়ান্ত প্রমাণ নয়।',
      pa: 'ਇਹ ਦਸਤਾਵੇਜ਼ ਕਿਸਾਨ ਦੀਆਂ ਫੋਟੋਆਂ ਅਤੇ ਅਧਿਕਾਰਤ ਡਰੋਨ ਫੋਟੋਆਂ ਦੇ ਆਧਾਰ ਤੇ ਤਿਆਰ ਕੀਤਾ ਤਕਨੀਕੀ ਰਿਕਾਰਡ ਹੈ। ਇਹ ਮਾਲਕੀ ਦਾ ਕਾਨੂੰਨੀ ਸਬੂਤ ਨਹੀਂ ਹੈ।',
      ml: 'കർഷകന്റെ ഫോട്ടോകളും ഡ്രോൺ ചിത്രങ്ങളും അടിസ്ഥാനമാക്കി തയ്യാറാക്കിയ സാങ്കേതിക റിപ്പോർട്ടാണിത്. ഇത് ഉടമസ്ഥാവകാശത്തിന്റെ നിയമപരമായ രേഖയല്ല.',
    },
