      te: '6 ధృవీకరించబడిన క్షేత్ర ఫోటోలు',
      kn: '6 ಪರಿಶೀಲಿಸಿದ ನೆಲದ ಫೋಟೋಗಳು',
      gu: '6 ચકાસાયેલ ગ્રાઉન્ડ ફોટોગ્રાફ્સ',
      bn: '৬টি যাচাইকৃত মাঠের ছবি',
