export function localizeDiscrepancies(text: string | undefined | null, lang: LanguageCode): string {
  if (!text) return '';
  if (lang === 'en') return text;

  if (text.includes('Negligible 0.02 acre buffer variation')) {
    const dict: Partial<Record<LanguageCode, string>> = {
      mr: 'पश्चिम बांधालगतच्या पाणंद रस्त्याशी केवळ ०.०२ एकर किरकोळ तफावत. कोणतीही सीमा अतिक्रमण नाही.',
      hi: 'पश्चिमी सीमा पर निकटवर्ती पगडंडी के साथ नगण्य 0.02 एकड़ का अंतर। कोई सीमा अतिक्रमण नहीं।',
      ta: 'மேற்கு எல்லை வரப்பில் அருகிலுள்ள பாதையுடன் புறக்கணிக்கத்தக்க 0.02 ஏக்கர் மாறுபாடு. எல்லை ஆக்கிரமிப்பு இல்லை.',
      te: 'పశ్చిమ సరిహద్దులో సమీప బండి బాటతో స్వల్ప 0.02 ఎకరాల వ్యత్యాసం. సరిహద్దు ఆక్రమణ లేదు.',
      kn: 'ಪಶ್ಚಿಮ ಗಡಿಯಲ್ಲಿ ಬಂಡಿ ದಾರಿಯೊಂದಿಗೆ ಕೇವಲ 0.02 ಎಕರೆ ಸಣ್ಣ ವ್ಯತ್ಯಾಸ. ಯಾವುದೇ ಗಡಿ ಅತಿಕ್ರಮಣವಿಲ್ಲ.',
      gu: 'પશ્ચિમ સરહદે નેળિયા સાથે માત્ર 0.02 એકરનો નજીવો તફાવત. કોઈ સરહદી દબાણ નથી.',
      bn: 'পশ্চিম সীমানায় সংলগ্ন রাস্তার সাথে নগণ্য ০.০২ একর পার্থক্য। কোনো সীমানা দখল নেই।',
      pa: 'ਪੱਛਮੀ ਹੱਦ ਤੇ ਰਸਤੇ ਨਾਲ ਮਾਮੂਲੀ 0.02 ਏਕੜ ਦਾ ਫਰਕ। ਕੋਈ ਕਬਜ਼ਾ ਨਹੀਂ।',
      ml: 'പടിഞ്ഞാറൻ അതിർത്തിയിൽ 0.02 ഏക്കറിന്റെ ചെറിയ വ്യത്യാസം. അതിക്രമിച്ചു കയറൽ ഇല്ല.',
    };
    return dict[lang] || text;
  }

  if (text.includes('No conflicting land boundary discrepancies detected')) {
    const dict: Partial<Record<LanguageCode, string>> = {
      mr: 'कोणतीही जमीन सीमा तफावत आढळली नाही.',
      hi: 'भूमि सीमा में कोई विसंगति नहीं पाई गई।',
      ta: 'நில எல்லை முரண்பாடுகள் எதுவும் கண்டறியப்படவில்லை.',
      te: 'ఎలాంటి భూ సరిహద్దు వ్యత్యాసాలు గుర్తించబడలేదు.',
      kn: 'ಯಾವುದೇ ಭೂ ಗಡಿ ವ್ಯತ್ಯಾಸಗಳು ಕಂಡುಬಂದಿಲ್ಲ.',
      gu: 'જમીનની સીમામાં કોઈ વિસંગતતા જોવા મળી નથી.',
      bn: 'কোনো জমির সীমানা অসঙ্গতি সনাক্ত হয়নি।',
      pa: 'ਕੋਈ ਜ਼ਮੀਨੀ ਹੱਦ ਵਿਸੰਗਤੀ ਨਹੀਂ ਮਿਲੀ।',
      ml: 'ഭൂമി അതിർത്തി വ്യത്യാസങ്ങളൊന്നും കണ്ടെത്തിയില്ല.',
    };
    return dict[lang] || text;
  }

  return text;
}

