  cropPhenologyDesc: {
    en: 'Whole-season Sentinel-2 NDVI spectral curve mapped against Maharashtra agro-climatic phenology templates for validated crop classification and growth tracking.',
    mr: 'प्रमाणित पीक वर्गीकरण आणि वाढीच्या ट्रॅकिंगसाठी महाराष्ट्र कृषी-हवामान फेनॉलॉजी नमुन्यांनुसार संपूर्ण हंगामातील सेंटिनेल-२ NDVI स्पेक्ट्रल वक्र.',
    hi: 'सत्यापित फसल वर्गीकरण एवं वृद्धि ट्रैकिंग के लिए महाराष्ट्र कृषि-जलवायु फेनोलॉजी मॉडल पर आधारित संपूर्ण-मौसम सेंटिनल-२ NDVI स्पेक्ट्रल वक्र।',
    ta: 'சரிபார்க்கப்பட்ட பயிர் வகைப்பாடு மற்றும் வளர்ச்சி கண்காணிப்புக்கான மகாராஷ்டிரா வேளாண் காலநிலை மாதிரிக்கு எதிரான சென்டினல்-2 NDVI நிறமாலை வளைவு.',
    te: 'ధృవీకరించబడిన పంట వర్గీకరణ మరియు పెరుగుదల ట్రాకింగ్ కోసం మహారాష్ట్ర వ్యవసాయ-వాతావరణ ఫినాలజీ నమూనాలకు మ్యాప్ చేయబడిన సెంటినెల్-2 NDVI స్పెక్ట్రల్ వక్రరేఖ.',
    kn: 'ದೃಢೀಕರಿಸಿದ ಬೆಳೆ ವರ್ಗೀಕರಣ ಮತ್ತು ಬೆಳವಣಿಗೆಯ ಟ್ರ್ಯಾಕಿಂಗ್‌ಗಾಗಿ ಮಹಾರಾಷ್ಟ್ರ ಕೃಷಿ-ಹವಾಮಾನ ಫಿನಾಲಜಿ ಮಾದರಿಗಳಿಗೆ ಹೊಂದಿಸಲಾದ ಸೆಂಟಿನೆಲ್-2 NDVI ಸ್ಪೆಕ್ಟ್ರಲ್ ಕರ್ವ್.',
    gu: 'પ્રમાણિત પાક વર્ગીકરણ અને વૃદ્ધિ ટ્રેકિંગ માટે મહારાષ્ટ્ર કૃષિ-આબોહવા ફેનોલોજી નમૂનાઓ અનુસાર સેન્ટિનેલ-૨ NDVI સ્પેક્ટ્રલ વળાંક.',
    bn: 'যাচাইকৃত শস্য শ্রেণীবিভাগ এবং বৃদ্ধির ট্র্যাকিংয়ের জন্য মহারাষ্ট্র কৃষি-জলবায়ু ফেনোলজি টেমপ্লেটের বিপরীতে সেন্টিনেল-২ এনডিভিআই স্পেকট্রাল বক্ররেখা।',
    pa: 'ਪ੍ਰਮਾਣਿਤ ਫ਼ਸਲ ਵਰਗੀਕਰਨ ਅਤੇ ਵਾਧਾ ਟਰੈਕਿੰਗ ਲਈ ਮਹਾਰਾਸ਼ਟਰ ਖੇਤੀਬਾੜੀ-ਜਲਵਾਯੂ ਫੀਨੋਲੋਜੀ ਮਾਡਲਾਂ ਅਨੁਸਾਰ ਪੂਰੇ ਸੀਜ਼ਨ ਦਾ ਸੈਂਟੀਨਲ-2 NDVI ਸਪੈਕਟ੍ਰਲ ਕਰਵ।',
    ml: 'സ്ഥിരീകരിച്ച വിള വർഗ്ഗീകരണത്തിനും വളർച്ചാ ട്രാക്കിംഗിനുമായി മഹാരാഷ്ട്ര കാർഷിക-കാലാവസ്ഥാ ഫിനോളജി ടെംപ്ലേറ്റുകളുമായി മാപ്പ് ചെയ്ത സെന്റിനൽ-2 NDVI സ്പെക്ട്രൽ കർവ്.',
  },
