export function localizePhenologyStage(stage: string | undefined | null, lang: LanguageCode): string {
  if (!stage) return '';
  return PHENOLOGY_TRANSLATIONS[stage]?.[lang] || PHENOLOGY_TRANSLATIONS[stage]?.en || stage;
}

