export function localizeGrowthSummary(summary: string | undefined | null, lang: LanguageCode): string {
  if (!summary) return '';
  if (lang === 'en') return summary;

  if (summary.includes('No clear satellite observation of this field is available')) {
    const noClearMap: Record<LanguageCode, string> = {
      en: summary,
      mr: 'निवडलेल्या हंगामासाठी या शेताचे कोणतेही निरभ्र उपग्रह निरीक्षण उपलब्ध नाही.',
      hi: 'चयनित मौसम के लिए इस खेत का कोई स्पष्ट उपग्रह अवलोकन उपलब्ध नहीं है।',
      ta: 'தேர்ந்தெடுக்கப்பட்ட பருவத்திற்கு இந்த பண்ணையின் தெளிவான செயற்கைக்கோள் அவதானிப்பு எதுவும் கிடைக்கவில்லை.',
      te: 'ఎంచుకున్న సీజన్ కోసం ఈ పొలానికి సంబంధించిన స్పష్టమైన ఉపగ్రహ పరిశీలన ఏదీ అందుబాటులో లేదు.',
      kn: 'ಆಯ್ಕೆಮಾಡಿದ ಋತುವಿಗೆ ಈ ಜಮೀನಿನ ಯಾವುದೇ ಸ್ಪಷ್ಟ ಉಪಗ್ರಹ ವೀಕ್ಷಣೆ ಲಭ್ಯವಿಲ್ಲ.',
      gu: 'પસંદ કરેલી મોસમ માટે આ ખેતરનું કોઈ સ્પષ્ટ સેટેલાઇટ અવલોકન ઉપલબ્ધ નથી.',
      bn: 'নির্বাচিত মরশুমের জন্য এই খামারের কোনো স্পষ্ট উপগ্রহ পর্যবেক্ষণ উপলব্ধ নেই।',
      pa: 'ਚੁਣੇ ਗਏ ਸੀਜ਼ਨ ਲਈ ਇਸ ਖੇਤ ਦਾ ਕੋਈ ਸਾਫ਼ ਸੈਟੇਲਾਈਟ ਨਿਰੀਖਣ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।',
      ml: 'തിരഞ്ഞെടുത്ത സീസണിൽ ഈ കൃഷിയിടത്തിന്റെ വ്യക്തമായ ഉപഗ്രഹ നിരീക്ഷണങ്ങളൊന്നും ലഭ്യമല്ല.',
    };
    return noClearMap[lang] || summary;
  }

  // Format: As of 2026-10-25, the field is at "Bare soil / pre-sowing" with mean NDVI 0.17 (-0.01 vs previous clear observation, trend stable). Season peak so far: 0.18 on 2026-10-15.
  const regex = /^As of ([0-9-]+), the field is at "([^"]+)" with mean NDVI ([0-9.-]+)(?: \(([+-]?[0-9.-]+) vs previous clear observation, trend ([a-zA-Z]+)\))?(?:\. Season peak so far: ([0-9.-]+) on ([0-9-]+)\.|\.)?/i;
  const match = summary.match(regex);
  if (!match) return summary;

  const [, date, stage, ndvi, delta, trend, peakVal, peakDate] = match;
  const locStage = localizePhenologyStage(stage, lang);
  const locTrend = trend ? TREND_TERMS[trend.toLowerCase()]?.[lang] || trend : '';

  if (lang === 'mr') {
    let res = `${date} रोजी, शेत "${locStage}" टप्प्यावर आहे (सरासरी NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, मागील निरभ्र नोंदीच्या तुलनेत ${delta}, कल ${locTrend}`;
    }
    res += ').';
    if (peakVal && peakDate) {
      res += ` हंगामातील आतापर्यंतचा उच्चांक: ${peakDate} रोजी ${peakVal}.`;
    }
    return res;
  }

  if (lang === 'hi') {
    let res = `${date} तक, खेत "${locStage}" अवस्था में है (औसत NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, पिछले स्पष्ट अवलोकन की तुलना में ${delta}, प्रवृत्ति ${locTrend}`;
    }
    res += ')।';
    if (peakVal && peakDate) {
      res += ` इस मौसम का अब तक का उच्चतम स्तर: ${peakDate} को ${peakVal}।`;
    }
    return res;
  }

  if (lang === 'ta') {
    let res = `${date} நிலவரப்படி, பண்ணை "${locStage}" நிலையில் உள்ளது (சராசரி NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, முந்தைய தெளிவான அவதானிப்புடன் ஒப்பிடும்போது ${delta}, போக்கு ${locTrend}`;
    }
    res += ').';
    if (peakVal && peakDate) {
      res += ` பருவத்தின் உச்ச வரம்பு: ${peakDate} அன்று ${peakVal}.`;
    }
    return res;
  }

  if (lang === 'te') {
    let res = `${date} నాటికి, పొలం "${locStage}" దశలో ఉంది (సగటు NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, మునుపటి స్పష్టమైన పరిశీలనతో పోలిస్తే ${delta}, ధోరణి ${locTrend}`;
    }
    res += ').';
    if (peakVal && peakDate) {
      res += ` ప్రస్తుత సీజన్ గరిష్టం: ${peakDate} న ${peakVal}.`;
    }
    return res;
  }

  if (lang === 'kn') {
    let res = `${date} ರ ಪ್ರಕಾರ, ಜಮೀನು "${locStage}" ಹಂತದಲ್ಲಿದೆ (ಸರಾಸರಿ NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, ಹಿಂದಿನ ಸ್ಪಷ್ಟ ವೀಕ್ಷಣೆಗೆ ಹೋಲಿಸಿದರೆ ${delta}, ಪ್ರವೃತ್ತಿ ${locTrend}`;
    }
    res += ').';
    if (peakVal && peakDate) {
      res += ` ಋತುವಿನ ಗರಿಷ್ಠ ಮಟ್ಟ: ${peakDate} ರಂದು ${peakVal}.`;
    }
    return res;
  }

  if (lang === 'gu') {
    let res = `${date} ના રોજ, ખેતર "${locStage}" તબક્કામાં છે (સરેરાશ NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, પાછલા સ્પષ્ટ અવલોકનની તુલનામાં ${delta}, વલણ ${locTrend}`;
    }
    res += ').';
    if (peakVal && peakDate) {
      res += ` સિઝનનો અત્યાર સુધીનો મહત્તમ સ્કોર: ${peakDate} ના રોજ ${peakVal}.`;
    }
    return res;
  }

  if (lang === 'bn') {
    let res = `${date} অনুযায়ী, খামারটি "${locStage}" পর্যায়ে রয়েছে (গড় NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, পূর্ববর্তী স্পষ্ট পর্যবেক্ষণের তুলনায় ${delta}, প্রবণতা ${locTrend}`;
    }
    res += ')।';
    if (peakVal && peakDate) {
      res += ` মরশুমের সর্বোচ্চ রেকর্ড: ${peakDate} তারিখে ${peakVal}।`;
    }
    return res;
  }

  if (lang === 'pa') {
    let res = `${date} ਤੱਕ, ਖੇਤ "${locStage}" ਪੜਾਅ 'ਤੇ ਹੈ (ਔਸਤ NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, ਪਿਛਲੇ ਸਾਫ਼ ਨਿਰੀਖਣ ਦੇ ਮੁਕਾਬਲੇ ${delta}, ਰੁਝਾਨ ${locTrend}`;
    }
    res += ')।';
    if (peakVal && peakDate) {
      res += ` ਸੀਜ਼ਨ ਦਾ ਹੁਣ ਤੱਕ ਦਾ ਸਿਖਰ: ${peakDate} ਨੂੰ ${peakVal}।`;
    }
    return res;
  }

  if (lang === 'ml') {
    let res = `${date} പ്രകാരം, കൃഷിയിടം "${locStage}" ഘട്ടത്തിലാണ് (ശരാശരി NDVI ${ndvi}`;
    if (delta && locTrend) {
      res += `, മുമ്പത്തെ വ്യക്തമായ നിരീക്ഷണവുമായി താരതമ്യപ്പെടുത്തുമ്പോൾ ${delta}, പ്രവണത ${locTrend}`;
    }
    res += ').';
    if (peakVal && peakDate) {
      res += ` സീസണിലെ ഏറ്റവും ഉയർന്ന നില: ${peakDate}-ൽ ${peakVal}.`;
    }
    return res;
  }

  return summary;
}

