export function localizeCropPatternName(pattern: string | undefined | null, lang: LanguageCode): string {
  if (!pattern) return '';
  if (CROP_PATTERN_NAMES[pattern]?.[lang]) return CROP_PATTERN_NAMES[pattern][lang];

  for (const [key, trans] of Object.entries(CROP_PATTERN_NAMES)) {
    if (pattern.startsWith(key) || pattern.toLowerCase().includes(key.toLowerCase())) {
      const parenMatch = pattern.match(/\((.*?)\)/);
      if (parenMatch && !key.includes('(')) {
        const localizedParen = localizeTypicalCrops(parenMatch[1].trim(), lang);
        return `${trans[lang] || trans.en} (${localizedParen})`;
      }
      return trans[lang] || trans.en;
    }
  }

  return CROP_PATTERN_NAMES[pattern]?.en || pattern;
}

