    pa: 'ਜਿਵੇਂ ਕਿ: ਝੋਨਾ (ਖੜ੍ਹਾ ਪਾਣੀ ਦੇਖਿਆ ਗਿਆ), ਸੋਇਆਬੀਨ, ਕਪਾਹ, ਮੱਕੀ',
