    hi: 'आधारभूत बुवाई एवं अंकुरण का पता चला। स्वस्थ प्रारंभिक ओज।',
    ta: 'விதைப்பு மற்றும் முளைப்பு கண்டறியப்பட்டது. ஆரோக்கியமான ஆரம்ப வீரியம்.',
