    bn: 'NDVI +0.11 সম্প্রসারণ। দ্রুত অঙ্গজ বৃদ্ধি এবং পাতার ক্ষেত্র বিকাশ।',
    pa: 'NDVI +0.11 ਵਾਧਾ। ਤੇਜ਼ ਬਨਸਪਤੀ ਵਾਧਾ ਅਤੇ ਪੱਤਿਆਂ ਦਾ ਖੇਤਰ ਵਿਕਾਸ।',
