    hi: 'मानसून बादल बाधा: कोई स्पष्ट सेंटिनल-२ अधिग्रहण SCL पिक्सेल सत्यापन पास नहीं कर सका।',
    ta: 'பருவமழை மேக மூட்டம்: தெளிவான சென்டினல்-2 பதிவு எதுவும் கிடைக்கவில்லை.',
    te: 'వర్షాకాల మేఘావృతం: స్పష్టమైన సెంటినెల్-2 డేటా ఏదీ ధృవీకరించబడలేదు.',
