export function localizeObservationChangeSummary(summary: string | undefined | null, lang: LanguageCode): string {
  if (!summary) return '';
  if (lang === 'en') return summary;

  if (CHANGE_SUMMARY_MAP[summary]) {
    return CHANGE_SUMMARY_MAP[summary][lang] || CHANGE_SUMMARY_MAP[summary].en || summary;
  }

  // Dynamic pattern: `${g.stage}. Mean NDVI ${g.ndvi.toFixed(2)} (${deltaNdvi} vs previous clear period)...`
  const match = summary.match(/^([^.]+)\. Mean NDVI ([0-9.-]+)(?: \(([+-]?[0-9.-]+) vs previous clear period\)\.|\.|\s*\(first clear period\)\.)/i);
  if (match) {
    const [, stage, ndvi, delta] = match;
    const locStage = localizePhenologyStage(stage, lang);
    if (lang === 'mr') {
      return `${locStage} टप्पा. सरासरी NDVI ${ndvi}${delta ? ` (मागील निरभ्र कालावधीच्या तुलनेत ${delta})` : ' (पहिली निरभ्र नोंद)'}.`;
    }
    if (lang === 'hi') {
      return `${locStage} चरण। औसत NDVI ${ndvi}${delta ? ` (पिछली स्पष्ट अवधि की तुलना में ${delta})` : ' (पहला स्पष्ट रिकॉर्ड)'}।`;
    }
    if (lang === 'ta') {
      return `${locStage} நிலை. சராசரி NDVI ${ndvi}${delta ? ` (முந்தைய தெளிவான காலத்துடன் ஒப்பிடும்போது ${delta})` : ''}.`;
    }
    if (lang === 'te') {
      return `${locStage} దశ. సగటు NDVI ${ndvi}${delta ? ` (మునుపటి స్పష్టమైన వ్యవధితో పోలిస్తే ${delta})` : ''}.`;
    }
    if (lang === 'kn') {
      return `${locStage} ಹಂತ. ಸರಾಸರಿ NDVI ${ndvi}${delta ? ` (ಹಿಂದಿನ ಸ್ಪಷ್ಟ ಅವಧಿಗೆ ಹೋಲಿಸಿದರೆ ${delta})` : ''}.`;
    }
    if (lang === 'gu') {
      return `${locStage} તબક્કો. સરેરાશ NDVI ${ndvi}${delta ? ` (પાછલા સ્પષ્ટ સમયગાળાની તુલનામાં ${delta})` : ''}.`;
    }
    if (lang === 'bn') {
      return `${locStage} পর্যায়। গড় NDVI ${ndvi}${delta ? ` (পূর্ববর্তী স্পষ্ট সময়ের তুলনায় ${delta})` : ''}।`;
    }
    if (lang === 'pa') {
      return `${locStage} ਪੜਾਅ। ਔਸਤ NDVI ${ndvi}${delta ? ` (ਪਿਛਲੀ ਸਾਫ਼ ਮਿਆਦ ਦੇ ਮੁਕਾਬਲੇ ${delta})` : ''}।`;
    }
    if (lang === 'ml') {
      return `${locStage} ഘട്ടം. ശരാശരി NDVI ${ndvi}${delta ? ` (മുമ്പത്തെ വ്യക്തമായ കാലയളവുമായി താരതമ്യപ്പെടുത്തുമ്പോൾ ${delta})` : ''}.`;
    }
  }

  return localizeMissingReason(summary, lang) || summary;
}

// Missing Reason Localizer
export function localizeMissingReason(reason: string | undefined | null, lang: LanguageCode): string {
  if (!reason) return '';
  if (lang === 'en') return reason;

  if (reason.includes('No Sentinel-2 pass over this field in the period')) {
    const map: Record<LanguageCode, string> = {
      en: reason,
      mr: 'या कालावधीत या शेतावरून कोणतीही सेंटिनेल-२ फेरी झालेली नाही.',
      hi: 'इस अवधि में इस खेत पर कोई सेंटिनल-२ पास नहीं हुआ।',
      ta: 'இக்காலத்தில் இந்த நிலத்தின் மீது சென்டினல்-2 பார்வை இல்லை.',
      te: 'ఈ కాలంలో ఈ పొలంపై సెంటినెల్-2 పాస్ లేదు.',
      kn: 'ಈ ಅವಧಿಯಲ್ಲಿ ಈ ಜಮೀನಿನ ಮೇಲೆ ಯಾವುದೇ ಸೆಂಟಿನೆಲ್-2 ಪಾಸ್ ಇಲ್ಲ.',
      gu: 'આ સમયગાળામાં આ ખેતર પર કોઈ સેન્ટિનેલ-૨ પાસ નથી.',
      bn: 'এই সময়ের মধ্যে এই খামারে কোনো সেন্টিনেল-২ পাস নেই।',
      pa: 'ਇਸ ਮਿਆਦ ਦੌਰਾਨ ਇਸ ਖੇਤ \'ਤੇ ਕੋਈ ਸੈਂਟੀਨਲ-2 ਪਾਸ ਨਹੀਂ ਸੀ।',
      ml: 'ഈ കാലയളവിൽ ഈ കൃഷിയിടത്തിൽ സെന്റിനൽ-2 പാസ് ഇല്ല.',
    };
    return map[lang] || reason;
  }

  if (reason.includes('Tile was cloud-covered') || reason.includes('cloud-covered or contaminated')) {
    const map: Record<LanguageCode, string> = {
      en: reason,
      mr: 'उपग्रह दृश्य ढगांनी आच्छादित किंवा अस्पष्ट होते.',
      hi: 'उपग्रह दृश्य बादलों से ढका या दूषित था।',
      ta: 'மேகமூட்டம் அல்லது தெளிவற்ற காட்சி.',
      te: 'క్లౌడ్ కవర్ లేదా అస్పష్టమైన దృశ్యం.',
      kn: 'ಮೋಡ ಕವಿದ ಅಥವಾ ಅಸ್ಪಷ್ಟ ದೃಶ್ಯ.',
      gu: 'વાદળછાયું અથવા અસ્પષ્ટ દ્રશ્ય.',
      bn: 'মেঘলা বা অস্পষ্ট দৃশ্য।',
      pa: 'ਬੱਦਲਾਂ ਨਾਲ ਢੱਕਿਆ ਜਾਂ ਅਸਪਸ਼ਟ ਦ੍ਰਿਸ਼।',
      ml: 'മേഘാവൃതമായ അല്ലെങ്കിൽ അവ്യക്തമായ ദൃശ്യം.',
    };
    return map[lang] || reason;
  }

  if (reason.includes('No clear satellite scene available')) {
    const map: Record<LanguageCode, string> = {
      en: reason,
      mr: 'कोणतेही निरभ्र उपग्रह दृश्य उपलब्ध नाही.',
      hi: 'कोई स्पष्ट उपग्रह दृश्य उपलब्ध नहीं है।',
      ta: 'தெளிவான செயற்கைக்கோள் காட்சி கிடைக்கவில்லை.',
      te: 'స్పష్టమైన ఉపగ్రహ దృశ్యం అందుబాటులో లేదు.',
      kn: 'ಯಾವುದೇ ಸ್ಪಷ್ಟ ಉಪಗ್ರಹ ದೃಶ್ಯ ಲಭ್ಯವಿಲ್ಲ.',
      gu: 'કોઈ સ્પષ્ટ સેટેલાઇટ દ્રશ્ય ઉપલબ્ધ નથી.',
      bn: 'কোনো স্বচ্ছ উপগ্রহ দৃশ্য উপলব্ধ নেই।',
      pa: 'ਕੋਈ ਸਾਫ਼ ਸੈਟੇਲਾਈਟ ਦ੍ਰਿਸ਼ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।',
      ml: 'വ്യക്തമായ ഉപഗ്രഹ ദൃശ്യം ലഭ്യമല്ല.',
    };
    return map[lang] || reason;
  }

  if (reason.includes('No usable satellite view')) {
    const map: Record<LanguageCode, string> = {
      en: reason,
      mr: 'कोणतेही वापरण्यायोग्य उपग्रह दृश्य नाही.',
      hi: 'कोई उपयोगी उपग्रह दृश्य नहीं।',
      ta: 'பயன்படுத்தக்கூடிய செயற்கைக்கோள் பார்வை இல்லை.',
      te: 'ఉపయోగించదగిన ఉపగ్రహ వీక్షణ లేదు.',
      kn: 'ಯಾವುದೇ ಬಳಸಬಹುದಾದ ಉಪಗ್ರಹ ನೋಟವಿಲ್ಲ.',
      gu: 'કોઈ વાપરી શકાય તેવું સેટેલાઇટ દ્રશ્ય નથી.',
      bn: 'কোনো ব্যবহারযোগ্য উপগ্রহ দৃশ্য নেই।',
      pa: 'ਕੋਈ ਵਰਤੋਂ ਯੋਗ ਸੈਟੇਲਾਈਟ ਦ੍ਰਿਸ਼ ਨਹੀਂ ਹੈ।',
      ml: 'ഉപയോഗപ്രദമായ ഉപഗ്രഹ കാഴ്ചയില്ല.',
    };
    return map[lang] || reason;
  }

  return reason;
}

// Period Label Localizer: "Period 1 (01 Jun - 15 Jun 2026)"
export function localizePeriodLabel(label: string | undefined | null, lang: LanguageCode): string {
  if (!label) return '';
  if (lang === 'en') return label;

  const match = label.match(/^Period (\d+)(?:\s*\(([^)]+)\))?/i);
  if (match) {
    const [, n, dates] = match;
    const periodWord: Record<LanguageCode, string> = {
      en: 'Period',
      mr: 'कालावधी',
      hi: 'अवधि',
      ta: 'காலம்',
      te: 'వ్యవధి',
      kn: 'ಅವಧಿ',
      gu: 'સમયગાળો',
      bn: 'সময়কাল',
      pa: 'ਮਿਆਦ',
      ml: 'കാലയളവ്',
    };
    const pWord = periodWord[lang] || 'Period';
    return dates ? `${pWord} ${n} (${dates})` : `${pWord} ${n}`;
  }
  return label;
}

