export function localizeNdviDensityClass(className: string | undefined | null, lang: LanguageCode): string {
  if (!className) return '';
  return NDVI_DENSITY_CLASSES[className]?.[lang] || NDVI_DENSITY_CLASSES[className]?.en || className;
}

