export function localizeAgronomicFinding(text: string | undefined | null, lang: LanguageCode): string {
  if (!text) return '';
  return AGRONOMIC_FINDINGS[text]?.[lang] || AGRONOMIC_FINDINGS[text]?.en || text;
}

