export function localizeIndexMeta(key: string, lang: LanguageCode): IndexMetaDetails {
  const item = INDEX_META_TRANSLATIONS[key]?.[lang] || INDEX_META_TRANSLATIONS[key]?.en;
  return item || {
    fullName: key.replace('_mean', '').toUpperCase(),
    description: 'Spectral telemetry index calculated from Copernicus Sentinel-2 L2A observations.',
  };
}

