    gu: 'પ્રમાણિત ડ્રોન પાયલોટ મોકલો, ઓર્થોમોઝેઇક તપાસો અને સરહદો પ્રમાણિત કરો.',
    bn: 'প্রত্যয়িত ড্রোন পাইলট পাঠান, অর্থোমোসাইক পরীক্ষা করুন এবং সীমানা প্রমাণীকরণ করুন।',
    pa: 'ਪ੍ਰਮਾਣਿਤ ਡਰੋਨ ਪਾਇਲਟ ਭੇਜੋ, ਆਰਥੋਮੋਜ਼ੈਕ ਦੀ ਜਾਂਚ ਕਰੋ ਅਤੇ ਹੱਦਾਂ ਨੂੰ ਪ੍ਰਮਾਣਿਤ ਕਰੋ।',
    ml: 'സാക്ഷ്യപ്പെടുത്തിയ ഡ്രോൺ പൈലറ്റുമാരെ അയയ്ക്കുക, ഓർത്തോമൊസൈക് പരിശോധിക്കുക, അതിർത്തികൾ സാക്ഷ്യപ്പെടുത്തുക.',
