    hi: 'मिशन आईडी, सर्वेक्षण संख्या, पायलट या गांव द्वारा खोजें...',
    ta: 'பணி ஐடி, நில எண், விமானி அல்லது கிராமம் மூலம் தேடவும்...',
    te: 'మిషన్ ఐడి, సర్వే నంబర్, పైలట్ లేదా గ్రామం ద్వారా శోధించండి...',
    kn: 'ಕಾರ್ಯಾಚರಣೆ ಐಡಿ, ಸರ್ವೆ ನಂಬರ್, ಪೈಲಟ್ ಅಥವಾ ಹಳ್ಳಿಯಿಂದ ಹುಡುಕಿ...',
    gu: 'મિશન આઈડી, સર્વે નંબર, પાયલોટ અથવા ગામ દ્વારા શોધો...',
    bn: 'মিশন আইডি, জরিপ নম্বর, পাইলট বা গ্রাম দ্বারা অনুসন্ধান করুন...',
